import { readFile, mkdir, rename, writeFile, rm } from 'node:fs/promises'
import { dirname, join } from 'node:path'
import { createId } from '@demicodes/utils'
import { GetObjectCommand, PutObjectCommand, S3Client } from '@aws-sdk/client-s3'

/** Keys are generated by the change store, never supplied by an HTTP caller. */
export interface ChangeObjects {
  put(key: string, bytes: Uint8Array): Promise<void>
  get(key: string): Promise<Uint8Array | null>
}

export class DirChangeObjects implements ChangeObjects {
  constructor(private readonly root: string) {}

  async put(key: string, bytes: Uint8Array): Promise<void> {
    const path = join(this.root, key)
    await mkdir(dirname(path), { recursive: true })
    const temporary = `${path}.${createId()}.tmp`
    try {
      await writeFile(temporary, bytes)
      await rename(temporary, path)
    } finally {
      await rm(temporary, { force: true })
    }
  }

  async get(key: string): Promise<Uint8Array | null> {
    try {
      return await readFile(join(this.root, key))
    } catch (error) {
      if ((error as NodeJS.ErrnoException).code === 'ENOENT') {
        return null
      }
      throw error
    }
  }
}

export class S3ChangeObjects implements ChangeObjects {
  constructor(private readonly client: S3Client, private readonly bucket: string) {}

  async put(key: string, bytes: Uint8Array): Promise<void> {
    await this.client.send(new PutObjectCommand({
      Bucket: this.bucket,
      Key: key,
      Body: bytes,
      ContentType: 'text/plain; charset=utf-8',
    }))
  }

  async get(key: string): Promise<Uint8Array | null> {
    try {
      const response = await this.client.send(new GetObjectCommand({
        Bucket: this.bucket,
        Key: key,
      }))
      if (!response.Body) {
        throw new Error('Change object has no response body')
      }
      return await response.Body.transformToByteArray()
    } catch (error) {
      if ((error as { name?: string }).name === 'NoSuchKey') {
        return null
      }
      throw error
    }
  }
}
